class Solution:
    def sortNumbers(self, nums: List[int]) -> List[int]:
        if len(nums) <= 1:
            return nums[:]
        mid = len(nums) // 2
        left = self.sortNumbers(nums[:mid])
        right = self.sortNumbers(nums[mid:])
        out = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                out.append(left[i])
                i += 1
            else:
                out.append(right[j])
                j += 1
        out.extend(left[i:])
        out.extend(right[j:])
        return out

