function sortNumbers(nums: number[]): number[] {
  const OFFSET = 50000;
  const count = new Array(2 * OFFSET + 1).fill(0);
  for (const x of nums) count[x + OFFSET]++;
  const out: number[] = [];
  for (let v = 0; v < count.length; v++) {
    for (let c = 0; c < count[v]; c++) out.push(v - OFFSET);
  }
  return out;
}

