class Solution:
    def sortNumbers(self, nums: List[int]) -> List[int]:
        offset = 50000
        count = [0] * (2 * offset + 1)
        for x in nums:
            count[x + offset] += 1
        out = []
        for v, c in enumerate(count):
            if c:
                out.extend([v - offset] * c)
        return out

